import { API_BASE_URL, apiClient } from "@/libs/api-client";
import { fetchList, fetchOne } from "@/libs/api-helpers";
import type { Page } from "@/types/api";
import type {
  AssignQuotePayload,
  CreateQuotePayload,
  CreateQuoteResponse,
  QuoteInquiry,
  QuoteListQuery,
  QuoteOverviewStats,
  UpdateQuoteStatusPayload,
} from "@/types/domain";

export const quoteService = {
  /**
   * Submit a new customer RFQ / quote inquiry and generate a WhatsApp click-to-chat deep link.
   * Supports optional custom `idempotencyKey` (auto-generated by request interceptor if omitted).
   */
  createQuote: async (
    payload: CreateQuotePayload,
    idempotencyKey?: string,
  ): Promise<CreateQuoteResponse> => {
    const res = await apiClient.post<CreateQuoteResponse>(
      "/api/v1/quotes",
      payload,
      idempotencyKey
        ? { headers: { "Idempotency-Key": idempotencyKey } }
        : undefined,
    );
    return res.data;
  },

  /**
   * Retrieve overview statistics of quote inquiries by status & urgency (Admin/Manager).
   */
  getQuoteOverviewStats: (): Promise<QuoteOverviewStats> =>
    fetchOne<QuoteOverviewStats>("/api/v1/quotes/stats/overview"),

  /**
   * List quote inquiries with pagination and optional status, priority, or search filters (Admin/Manager).
   */
  listQuotes: (params?: QuoteListQuery): Promise<Page<QuoteInquiry>> =>
    fetchList<QuoteInquiry>("/api/v1/quotes", { params }),

  /**
   * Retrieve full quote inquiry details by its reference code (e.g., `ELP-20261028-4821`).
   */
  getQuoteByReference: (reference: string): Promise<QuoteInquiry> =>
    fetchOne<QuoteInquiry>(`/api/v1/quotes/${encodeURIComponent(reference)}`),

  /**
   * Download official Proforma Quote PDF document as a Blob.
   */
  downloadQuotePdf: async (reference: string): Promise<Blob> => {
    const res = await apiClient.get<Blob>(
      `/api/v1/quotes/${encodeURIComponent(reference)}/pdf`,
      {
        responseType: "blob",
      },
    );
    return res.data;
  },

  /**
   * Helper to get the direct URL for downloading/viewing a quote PDF.
   */
  getQuotePdfUrl: (reference: string): string => {
    const cleanRoot = API_BASE_URL.trim()
      .replace(/\/+$/, "")
      .replace(/\/(api\/)?v1$/i, "");
    return `${cleanRoot}/api/v1/quotes/${encodeURIComponent(reference)}/pdf`;
  },

  /**
   * Update a quote inquiry's lifecycle status and optional internal admin notes (Admin/Manager).
   */
  updateQuoteStatus: async (
    id: string,
    payload: UpdateQuoteStatusPayload,
  ): Promise<QuoteInquiry> => {
    const res = await apiClient.patch<QuoteInquiry>(
      `/api/v1/quotes/${id}/status`,
      payload,
    );
    return res.data;
  },

  /**
   * Assign a quote inquiry to a Supervising Manager or Super-Admin (Super-Admin only).
   */
  assignQuote: async (
    id: string,
    payload: AssignQuotePayload,
  ): Promise<QuoteInquiry> => {
    const res = await apiClient.patch<QuoteInquiry>(
      `/api/v1/quotes/${id}/assign`,
      payload,
    );
    return res.data;
  },

  /**
   * Permanently delete a quote inquiry record (Super-Admin only).
   */
  deleteQuote: async (id: string) => {
    const res = await apiClient.delete(`/api/v1/quotes/${id}`);
    return res.data;
  },
};

